def verify_isbn(isbn: str) -> str:
    # Remove hyphens and convert to title case
    isbn_clean = isbn.replace('-', '').title()

    # Check if ISBN format is correct
    if len(isbn_clean) != 13 or not isbn_clean[3].isdigit() or not isbn_clean[6].isdigit()):
        return isbn

    # Calculate the checksum
    def calculate_checksum(isbn):
        digits = list(isbn)[::-1]
        return sum((int(d) if d.isdigit() else 10 + int(d)) * i for i, d in enumerate(digits))

    checksum = calculate_checksum(isbn_clean)

    # Check if the checksum is correct
    if checksum == 0:
        return "Right"
    elif checksum % 10 == 0:
        return "Right"
    else:
        return isbn[:5] + str(checksum - checksum % 10)

def count_passing_ways(n: int, m: int) -> int:
    if n == 0: return 0

    dp = [[0] * (m + 1) for _ in range(n)]

    # Initialize the base cases
    dp[0][0] = 1  # There is one way to do nothing (passing the ball 0 times)

    for i in range(1, n):
        for j in range(1, m + 1):
            # The student can either pass the ball to the left neighbor or to the right neighbor
            if j > 0:
                dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % (10**9 + 7)

    # The number of passing ways that result in the ball returning to the starting student
    return dp[n - 1][m]

