def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, statements in statements.items():
        if participant in liar_count:
            # If the participant is a liar, the statements about their guilt should not match
            return False
        # Check if every other participant's statement is consistent
        for other_participant in set(statements) - {participant} - liar_count:
            if not all(statement in statements[other_participant] for statement in statements[participant]):
                return False

    return True

def remaining_trees_after_clearing(l, areas):
    count = l  # Initialize the count of trees to the total length
    for start, end in areas:
        if start < end:
            count -= (end - start - 1)  # Subtract the number of removed trees in the current area
    return count

def calculate_arrangements(n, m, a):
    mod = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There is one way to arrange 0 pots with any number of flower types
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(max(0, j - a[i - 1]), j + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][k]) % mod

    return dp[n][m]

def find_most_unhappy_day(schedule) -> int:
    MAX_UNHAPPY = 8
    total_hours = [0] * 7

    for day, school_hours, extra_classes in schedule:
        total_hours[day-1] += school_hours
        total_hours[day-1] += extra_classes

    most_unhappy_day = 0
    max_unhappiness = 0

    for day in range(7):
        if total_hours[day] > MAX_UNHAPPY and total_hours[day] - MAX_UNHAPPY > max_unhappiness:
            max_unhappiness = total_hours[day] - MAX_UNHAPPY
            most_unhappy_day = day

    return most_unhappy_day + 1 if max_unhappiness != 0 else 0

