def minimum_students_to_leave(heights):
    left = 0
    right = len(heights) - 1
    decrease_count = 0

    while right > left:
        while right > left and heights[right] >= heights[right - 1]:
            decrease_count += 1
            if decrease_count > 2:
                right -= 1
            else:
                if heights[left] < heights[right]:
                    break
        left += 1
        right = len(heights) - 1 - decrease_count

    return right - left + 1

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        return 4 * n * (n - 1) + 2
